if(args.Contains("--package-smoke")){
    var package=Environment.GetEnvironmentVariable("MACROSTUDIO_PACKAGE_DIRECTORY")??throw new Exception("Set MACROSTUDIO_PACKAGE_DIRECTORY.");
    using var gui=Process.Start(new ProcessStartInfo(Path.Combine(Path.GetFullPath(package),"MacroStudio.exe")){UseShellExecute=false})!;
    try{gui.WaitForInputIdle(6000);await Task.Delay(1500);gui.Refresh();if(gui.HasExited||gui.MainWindowHandle==0||!gui.MainWindowTitle.Contains("MacroStudio"))throw new Exception("Packaged GUI did not show its main window.");var title=gui.MainWindowTitle;if(!gui.CloseMainWindow())throw new Exception("Packaged GUI could not close.");using var done=new CancellationTokenSource(6000);await gui.WaitForExitAsync(done.Token);if(gui.ExitCode!=0)throw new Exception("Packaged GUI exit "+gui.ExitCode);var directory=Path.GetFullPath("work/advanced-verification");Directory.CreateDirectory(directory);await File.WriteAllTextAsync(Path.Combine(directory,"gui-smoke.json"),JsonSerializer.Serialize(new{MainWindowShown=true,Title=title,CleanShutdown=true,ExitCode=gui.ExitCode}));Console.WriteLine("PASS packaged GUI startup, main window and clean shutdown");return 0;}finally{if(!gui.HasExited)gui.CloseMainWindow();}
}

var tests=new List<(string,Func<Task>)>();
Native.SetProcessDpiAwarenessContext(-4);
void Check(bool ok,string message="Assertion failed"){if(!ok)throw new Exception(message);}
void Add(string name,Action action)=>tests.Add((name,()=>{action();return Task.CompletedTask;}));
void Reject<T>(Action action)where T:Exception{try{action();}catch(T){return;}throw new Exception("Expected "+typeof(T).Name);}
Mat Template(){var mat=new Mat(40,72,MatType.CV_8UC3,new Scalar(25,55,85));Cv2.Rectangle(mat,new Rect(2,2,22,30),new Scalar(240,30,160),-1);Cv2.PutText(mat,"X7",new Point(26,28),HersheyFonts.HersheySimplex,.7,new Scalar(255,255,255),2);return mat;}
Add("image fixture: shifted target and strip-boundary match",()=>{using var t=Template();using var s=new Mat(360,480,MatType.CV_8UC3,new Scalar(245,245,245));using(var roi=new Mat(s,new Rect(275,125,t.Width,t.Height)))t.CopyTo(roi);var m=ImageMatcher.Find(s,t,.94);Check(m is {X:275,Y:125}&&m.Score>.99);});
Add("image fixture: absent, low-information and ambiguous targets",()=>{using var t=Template();using var s=new Mat(240,400,MatType.CV_8UC3,Scalar.All(240));Check(ImageMatcher.Find(s,t,.94)==null);using var plain=new Mat(40,60,MatType.CV_8UC3,Scalar.All(90));Reject<InvalidDataException>(()=>ImageMatcher.Find(s,plain,.94));using(var a=new Mat(s,new Rect(20,20,t.Width,t.Height)))t.CopyTo(a);using(var b=new Mat(s,new Rect(250,150,t.Width,t.Height)))t.CopyTo(b);Reject<InvalidOperationException>(()=>ImageMatcher.Find(s,t,.94));});
Add("image fixture: scaling settings and pre-cancelled matching rejected",()=>{using var t=Template();using var s=new Mat(240,400,MatType.CV_8UC3,Scalar.All(240));using var c=new CancellationTokenSource();c.Cancel();Reject<OperationCanceledException>(()=>ImageMatcher.Find(s,t,.94,c.Token));Reject<InvalidDataException>(()=>MacroStore.Validate(new(){Actions=[new(){Detection=new(){Scale=1.25}}]}));});
tests.Add(("detection polling timeout, pause checkpoint and cancellation",async()=>{int checkpoints=0;var ctx=new AutomationContext{Checkpoint=t=>{checkpoints++;return Task.CompletedTask;}};try{await WindowsAutomationHost.PollAsync(new(){TimeoutMs=80,PollMs=20},ctx,default,()=>false);throw new Exception("No timeout");}catch(TimeoutException){}Check(checkpoints>=3);using var c=new CancellationTokenSource(50);var sw=Stopwatch.StartNew();try{await WindowsAutomationHost.PollAsync(new(){TimeoutMs=60000,PollMs=20},ctx,c.Token,()=>false);throw new Exception("No cancellation");}catch(OperationCanceledException){}Check(sw.ElapsedMilliseconds<500);}));
Add("visual recording: click pairs convert and drags remain native",()=>{var d=new DetectionSettings{Image="fixture.png"};var click=RecordingService.Assemble([new(10,0x201,20,30,0,0,0,false,0,Visual:d),new(40,0x202,20,30,0,0,0,false,0)],CoordinateMode.Desktop);Check(click.Count==1&&click[0].Kind==ActionKind.ImageClick&&!click[0].Detection.CoordinateFallback);var drag=RecordingService.Assemble([new(10,0x201,20,30,0,0,0,false,0,Visual:d),new(20,0x200,40,30,0,0,0,false,0),new(40,0x202,40,30,0,0,0,false,0)],CoordinateMode.Desktop);Check(drag.Count==3&&drag[0].Kind==ActionKind.MouseButton);});

Add("typed variables, substitution, numeric bindings and invalid values",()=>{var v=new VariableStore();v.Set("n",new(VariableType.Number,"12.5"));v.Set("point",new(VariableType.Coordinates,"-50,300"));Check(v.Substitute("${n} at ${point.x},${point.y}")=="12.5 at -50,300");var a=v.Resolve(new(){Kind=ActionKind.MouseButton,Bindings=new(){{"x","${point.x}"},{"y","${point.y}"}}});Check(a.X==-50&&a.Y==300);Reject<InvalidDataException>(()=>v.Set("n",new(VariableType.Number,"NaN")));Reject<InvalidOperationException>(()=>v.Substitute("${missing}"));Reject<InvalidDataException>(()=>v.Resolve(new(){Bindings=new(){{"kind","1"}}}));});
Add("arithmetic, comparisons and CSV quoted multiline round trip",()=>{var ctx=new AutomationContext();Check(DataOperations.Execute(new(){Kind=ActionKind.Calculate,Data=new(){Variable="sum",Value="8",Operand="3",Operation="*"}},ctx));Check(ctx.Variables.Get("sum").Value=="24");Check(DataOperations.Compare("24",">","5"));var rows=new List<List<string>>{new(){"a,b","one\r\ntwo","say \"yes\"",""}};Check(CsvData.Parse(CsvData.Serialize(rows))[0].SequenceEqual(rows[0]));Reject<InvalidDataException>(()=>CsvData.Parse("\"unterminated"));});
tests.Add(("text and CSV read/write preserve data",async()=>{var dir=Path.Combine(Path.GetTempPath(),"MacroStudio-data-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{var ctx=new AutomationContext{BaseDirectory=dir};var host=new WindowsAutomationHost(new TestSink());await host.ExecuteAsync(new(){Kind=ActionKind.WriteText,Data=new(){File="test.txt",Value="hello λ"}},ctx,default);await host.ExecuteAsync(new(){Kind=ActionKind.ReadText,Data=new(){File="test.txt",Variable="text"}},ctx,default);Check(ctx.Variables.Get("text").Value=="hello λ");await host.ExecuteAsync(new(){Kind=ActionKind.WriteCsv,Data=new(){File="test.csv",Row=1,Column=2,Value="a,\"b\""}},ctx,default);await host.ExecuteAsync(new(){Kind=ActionKind.ReadCsv,Data=new(){File="test.csv",Row=1,Column=2,Variable="cell"}},ctx,default);Check(ctx.Variables.Get("cell").Value=="a,\"b\"");}finally{Directory.Delete(dir,true);}}));
tests.Add(("local Windows OCR fixture to typed variable to text injection sink",async()=>{using var image=new Mat(130,900,MatType.CV_8UC3,Scalar.All(255));Cv2.PutText(image,"AUTOMATION READY 42",new Point(18,85),HersheyFonts.HersheySimplex,1.7,Scalar.All(0),3);var result=await WindowsAutomationHost.RecognizeAsync(image,new(0,0,image.Width,image.Height),"en-US",default);Check(result.Text.Contains("READY")&&result.Text.Contains("42"),"OCR result: "+result.Text);var sink=new TestSink();var engine=new PlaybackEngine(sink,new());await engine.PlayAsync([new(){Kind=ActionKind.SetVariable,Data=new(){Variable="ocr",Value=result.Text}},new(){Kind=ActionKind.Text,Text="${ocr}"}],new());Check(sink.Text==result.Text);}));

tests.Add(("flow: variables, conditional branch and bounded repeat",async()=>{
    var sink=new TestSink();var engine=new PlaybackEngine(sink,new());await engine.PlayAsync([
        new(){Kind=ActionKind.SetVariable,Data=new(){Variable="n",Type=VariableType.Number,Value="0"}},new(){Kind=ActionKind.RepeatStart,Flow=new(){Count=3}},new(){Kind=ActionKind.Calculate,Data=new(){Variable="n",Value="${n}",Operand="1",Operation="+"}},new(){Kind=ActionKind.RepeatEnd},new(){Kind=ActionKind.Branch,Data=new(){Value="${n}",Operation="==",Operand="3"},Flow=new(){Destination="yes",Otherwise="no"}},new(){Kind=ActionKind.Label,Flow=new(){Label="no"}},new(){Kind=ActionKind.Text,Text="FAIL"},new(){Kind=ActionKind.Jump,Flow=new(){Destination="end"}},new(){Kind=ActionKind.Label,Flow=new(){Label="yes"}},new(){Kind=ActionKind.Text,Text="OK:${n}"},new(){Kind=ActionKind.Label,Flow=new(){Label="end"}}
    ],new());Check(sink.Text=="OK:3");
}));
tests.Add(("flow: timeout retries are bounded and jump selects label",async()=>{var sink=new TestSink();var host=new TimeoutHost();var engine=new PlaybackEngine(sink,new(),host);await engine.PlayAsync([new(){Kind=ActionKind.WaitRegionChange,Flow=new(){Timeout=TimeoutPolicy.Retry,Retries=2}},new(){Kind=ActionKind.WaitRegionChange,Flow=new(){Timeout=TimeoutPolicy.Jump,Destination="done"}},new(){Kind=ActionKind.Text,Text="FAIL"},new(){Kind=ActionKind.Label,Flow=new(){Label="done"}},new(){Kind=ActionKind.Text,Text="OK"}],new());Check(host.Count==4&&sink.Text=="OK"&&engine.Logs.Count(l=>l.Level=="Retry")==2);}));
tests.Add(("flow: validation rejects missing labels/assets and unbalanced repeats before injection",async()=>{var sink=new TestSink();var engine=new PlaybackEngine(sink,new());foreach(var action in new[]{new MacroAction{Kind=ActionKind.Jump,Flow=new(){Destination="missing"}},new(){Kind=ActionKind.RepeatStart},new(){Kind=ActionKind.ImageClick,Detection=new(){Image="not-present.png"}},new(){Kind=ActionKind.SetVariable,Data=new(){Type=VariableType.Number,Value="NaN"}}}){try{await engine.PlayAsync([new(){Kind=ActionKind.Text,Text="FAIL"},action],new());throw new Exception("Invalid program accepted");}catch(InvalidDataException){}}Check(sink.Text=="");}));
tests.Add(("flow: recursive calls rejected; nested wait cancellation releases input",async()=>{var dir=Path.Combine(Path.GetTempPath(),"MacroStudio-flow-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{var child=Path.Combine(dir,"child.json");await MacroStore.SaveAsync(child,new(){Actions=[new(){Kind=ActionKind.CallMacro,Flow=new(){MacroFile="child.json"}}]});try{await MacroProgram.BuildAsync([new(){Kind=ActionKind.CallMacro,Flow=new(){MacroFile="child.json"}}],dir);throw new Exception("Recursive call accepted");}catch(InvalidDataException){}await MacroStore.SaveAsync(child,new(){Actions=[new(){Kind=ActionKind.Key,VirtualKey=17,IsDown=true},new(){Kind=ActionKind.Delay,DurationMs=60000}]});var sink=new TestSink();var session=new SessionMachine();var engine=new PlaybackEngine(sink,session){BaseDirectory=dir};using var cancel=new CancellationTokenSource(80);var sw=Stopwatch.StartNew();try{await engine.PlayAsync([new(){Kind=ActionKind.CallMacro,Flow=new(){MacroFile="child.json"}}],new(),cancel.Token);throw new Exception("No cancellation");}catch(OperationCanceledException){}Check(sw.ElapsedMilliseconds<500&&session.State==SessionState.Idle&&sink.Releases==1);}finally{Directory.Delete(dir,true);}}));
tests.Add(("debugger: breakpoint and single-step retain paused variables",async()=>{var sink=new TestSink();var session=new SessionMachine();var engine=new PlaybackEngine(sink,session);var task=engine.PlayAsync([new(){Kind=ActionKind.SetVariable,Breakpoint=true,Data=new(){Variable="n",Value="value"}},new(){Kind=ActionKind.Text,Text="${n}"}],new());for(int i=0;i<100&&session.State!=SessionState.Paused;i++)await Task.Delay(5);Check(session.State==SessionState.Paused&&sink.Text=="");engine.Step();for(int i=0;i<100;i++){if(session.State==SessionState.Paused&&engine.Context!.Variables.Snapshot().ContainsKey("n"))break;await Task.Delay(5);}Check(session.State==SessionState.Paused&&engine.Context!.Variables.Get("n").Value=="value"&&sink.Text=="");engine.Step();await task;Check(sink.Text=="value");}));
Add("mouse paths: linear and curved preserve endpoints and timing",()=>{var a=new MacroAction{DurationMs=100,Path=[new(0,0,0),new(100,0,100)]};var line=MousePaths.Shape(a,MousePathShape.Linear);var curve=MousePaths.Shape(a,MousePathShape.Curved);Check(line[0].X==0&&line[^1].X==100&&line[^1].OffsetMs==100&&line.All(p=>p.Y==0));Check(curve[0].X==0&&curve[^1].X==100&&curve.Any(p=>p.Y!=0));});

tests.Add(("portable package: images and nested macro survive source removal",async()=>{var dir=Path.Combine(Path.GetTempPath(),"MacroStudio-package-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{var source=Path.Combine(dir,"source");Directory.CreateDirectory(source);using(var t=Template())t.SaveImage(Path.Combine(source,"target.png"));await MacroStore.SaveAsync(Path.Combine(source,"child.json"),new(){Actions=[new(){Kind=ActionKind.WaitImage,Detection=new(){Image="target.png"}}]});var doc=new MacroDocument{Actions=[new(){Kind=ActionKind.ImageClick,Detection=new(){Image="target.png"}},new(){Kind=ActionKind.CallMacro,Flow=new(){MacroFile="child.json"}}]};var zip=Path.Combine(dir,"macro.macrozip");await PortablePackage.ExportAsync(zip,doc,source);Directory.Delete(source,true);var imported=await PortablePackage.ImportAsync(zip,Path.Combine(dir,"imported"));var restored=await MacroStore.LoadAsync(imported);var plan=await MacroProgram.BuildAsync(restored.Actions,Path.GetDirectoryName(imported)!,imported);Check(plan.Calls.Count==1&&File.Exists(Path.Combine(Path.GetDirectoryName(imported)!,restored.Actions[0].Detection.Image)));}finally{Directory.Delete(dir,true);}}));
tests.Add(("portable package: traversal and external references rejected",async()=>{var dir=Path.Combine(Path.GetTempPath(),"MacroStudio-unsafe-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{var zip=Path.Combine(dir,"unsafe.macrozip");using(var file=File.Create(zip))using(var archive=new System.IO.Compression.ZipArchive(file,System.IO.Compression.ZipArchiveMode.Create)){using var writer=new StreamWriter(archive.CreateEntry("../escape.json").Open());writer.Write("{}");}try{await PortablePackage.ImportAsync(zip,Path.Combine(dir,"bad"));throw new Exception("Traversal accepted");}catch(InvalidDataException){}Check(!Directory.Exists(Path.Combine(dir,"bad")));}finally{Directory.Delete(dir,true);}}));
tests.Add(("local library: folders, name/path search and persistent favorites/hotkeys",async()=>{var dir=Path.Combine(Path.GetTempPath(),"MacroStudio-library-"+Guid.NewGuid());try{var library=new LocalLibrary(dir);library.CreateFolder("Work/Finance");var file=library.Resolve("Work/Finance/monthly.json");await MacroStore.SaveAsync(file,new(){Name="Monthly task"});library.SavePreference("Work/Finance/monthly.json",true,"Ctrl+Shift+F6");var next=new LocalLibrary(dir);var entry=next.Search("monthly",true).Single();Check(entry.Favorite&&entry.Hotkey=="Ctrl+Shift+F6"&&next.Search("finance").Count==1);Reject<InvalidDataException>(()=>next.Resolve("../escape"));}finally{if(Directory.Exists(dir))Directory.Delete(dir,true);}}));

tests.Add(("AI: disabled makes no request; both protocols validate typed JSON",async()=>{var handler=new ProviderFixture();using var client=new System.Net.Http.HttpClient(handler);var config=new AiConfiguration{Model="fixture"};try{await new JsonChatProvider(client,config).ProcessAsync(new("input",null,VariableType.Number),default);throw new Exception("Disabled AI ran");}catch(InvalidOperationException){}Check(handler.Calls==0);config.Enabled=true;var provider=new JsonChatProvider(client,config);var number=await provider.ProcessAsync(new("input",null,VariableType.Number),default);Check(number is {Type:VariableType.Number,Value:"42"});config.Protocol=AiProtocol.ChatCompletions;var other=await provider.ProcessAsync(new("image",[1,2,3],VariableType.Number),default);Check(other.Value=="42"&&handler.ImageSeen&&handler.SchemaSeen);Reject<InvalidDataException>(()=>JsonChatProvider.ValidateOutput("{\"value\":\"run a command\",\"actions\":[]}",VariableType.Text));Reject<InvalidDataException>(()=>JsonChatProvider.ValidateOutput("{\"value\":\"42\"}",VariableType.Number));Check(JsonChatProvider.ValidateOutput("{\"value\":{\"x\":-1,\"y\":200}}",VariableType.Coordinates).Value=="-1,200");}));
tests.Add(("AI: timeout and cancellation interrupt provider work",async()=>{var handler=new ProviderFixture{Delay=true};using var client=new System.Net.Http.HttpClient(handler);var config=new AiConfiguration{Enabled=true,Model="fixture",TimeoutSeconds=1};var provider=new JsonChatProvider(client,config);try{await provider.ProcessAsync(new("input",null,VariableType.Text),default);throw new Exception("Provider did not time out");}catch(TimeoutException){}using var c=new CancellationTokenSource(30);var sw=Stopwatch.StartNew();try{await provider.ProcessAsync(new("input",null,VariableType.Text),c.Token);throw new Exception("Provider did not cancel");}catch(OperationCanceledException){}Check(sw.ElapsedMilliseconds<500);}));
