tests.Add(("preflight: low-detail template and literal division by zero stop before input",async()=>{var dir=Path.Combine(Path.GetTempPath(),"MacroStudio-preflight-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{var file=Path.Combine(dir,"plain.png");using(var plain=new Mat(30,50,MatType.CV_8UC3,Scalar.All(70)))plain.SaveImage(file);var sink=new TestSink();var engine=new PlaybackEngine(sink,new(),new WindowsAutomationHost(sink));foreach(var a in new[]{new MacroAction{Kind=ActionKind.ImageClick,Detection=new(){Image=file}},new(){Kind=ActionKind.Calculate,Data=new(){Value="3",Operand="0",Operation="/"}}}){try{await engine.PlayAsync([new(){Kind=ActionKind.Text,Text="FAIL"},a],new());throw new Exception("Invalid preflight accepted");}catch(InvalidDataException){}}Check(sink.Text=="");}finally{Directory.Delete(dir,true);}}));
Add("v1 fixtures remain readable; numeric region and repeat-count bindings resolve",()=>{foreach(var path in Directory.EnumerateFiles("samples","*.json",SearchOption.TopDirectoryOnly)){var doc=MacroStore.Parse(File.ReadAllText(path));Check(doc.Actions.Count>0);Check(MacroStore.Parse(MacroStore.Serialize(doc)).Actions.Count==doc.Actions.Count);}var vars=new VariableStore();vars.Set("n",new(VariableType.Number,"3"));var resolved=vars.Resolve(new(){Kind=ActionKind.RepeatStart,Detection=new(){Region=new(1,2,10,20)},Bindings=new(){{"flow.count","${n}"},{"detection.region.width","${n}"}}});Check(resolved.Flow.Count==3&&resolved.Detection.Region!.Width==3);});

if(args.Contains("--live"))tests.Add(("LIVE: moved click, delayed appearance, disappearance and absent timeout",async()=>{
    var root=Path.GetFullPath("work/advanced-verification");Directory.CreateDirectory(root);var probe=Path.Combine(root,"lab.json");if(File.Exists(probe))File.Delete(probe);
    var exe=Environment.GetEnvironmentVariable("MACROSTUDIO_LAB_EXE")??Path.GetFullPath("src/MacroStudio.TestLab/bin/Release/net10.0-windows10.0.19041.0/MacroStudio.TestLab.exe");
    var gate=Path.Combine(root,"start-"+Guid.NewGuid()+".signal");
    using var lab=Process.Start(new ProcessStartInfo(exe){ArgumentList={"--visual","--scenario","--probe",probe,"--start-gate",gate}})!;
    IInputSink? cleanup=null;
    try{
        var watch=Stopwatch.StartNew();while(!File.Exists(probe)&&watch.ElapsedMilliseconds<5000)await Task.Delay(40);await Task.Delay(400);
        JsonElement Read()=>JsonDocument.Parse(File.ReadAllText(probe)).RootElement.Clone();
        ScreenRegion Region(JsonElement r)=>new(r.GetProperty("X").GetInt32(),r.GetProperty("Y").GetInt32(),r.GetProperty("Width").GetInt32(),r.GetProperty("Height").GetInt32());
        lab.Refresh();var handle=lab.MainWindowHandle;Console.WriteLine("WAIT: activate MacroStudio Visual Lab; no input until it has focus (120 seconds).");
        for(int i=0;i<1200&&Native.GetForegroundWindow()!=handle;i++)await Task.Delay(100);
        Check(Native.GetForegroundWindow()==handle,"Visual Lab was not activated; no input sent.");await Task.Delay(200);
        var initial=Read();var r=Region(initial.GetProperty("Target"));var template=Path.Combine(root,"target.png");using(var image=ScreenCapture.Grab(r))image.SaveImage(template);await File.WriteAllTextAsync(gate,"start");
        using var timeout=new CancellationTokenSource(15000);using var hooks=new HookService();await hooks.ConfigureAsync([new("Stop",0,27)],false);hooks.Control+=_=>timeout.Cancel();var input=new GuardedSink(new WindowsInput(),()=>Native.GetForegroundWindow()==handle);cleanup=input;var host=new WindowsAutomationHost(input);var context=new AutomationContext();
        input.Focus(new("MacroStudio.TestLab","MacroStudio Visual Lab",0,0,900,600),false);await Task.Delay(150);
        var click=new MacroAction{Kind=ActionKind.ImageClick,Detection=new(){Image=template,OffsetX=r.Width/2,OffsetY=r.Height/2,TemplateDpi=initial.GetProperty("Dpi").GetDouble(),TimeoutMs=5000}};
        var window=WindowCatalog.Describe(handle)!;
        click.Detection.Region=new(window.Left,window.Top,window.Width,window.Height);
        await host.ExecuteAsync(new(){Kind=ActionKind.WaitRegionChange,Detection=new(){Region=r,TimeoutMs=5000,ChangeFraction=.1}},context,timeout.Token);
        Check(Region(Read().GetProperty("Target")).X!=r.X,"Target did not move");
        await host.ExecuteAsync(click,context,timeout.Token);await Task.Delay(150);Check(Read().GetProperty("Clicks").GetInt32()==1,"Moved target was not clicked");
        await host.ExecuteAsync(new(){Kind=ActionKind.WaitImageGone,Detection=click.Detection},context,timeout.Token);
        Check(!Read().GetProperty("Visible").GetBoolean(),"Delayed target should still be absent when image click starts");
        watch.Restart();await host.ExecuteAsync(click,context,timeout.Token);await Task.Delay(150);Check(Read().GetProperty("Clicks").GetInt32()==2&&watch.ElapsedMilliseconds>500,"Did not wait for delayed target");
        click.Detection.TimeoutMs=350;watch.Restart();try{await host.ExecuteAsync(click,context,timeout.Token);throw new Exception("Absent target did not stop");}catch(TimeoutException){}Check(Read().GetProperty("Clicks").GetInt32()==2&&watch.ElapsedMilliseconds<1500);
        long absentMs=watch.ElapsedMilliseconds;var ocr=Region(Read().GetProperty("Ocr"));var entry=Region(Read().GetProperty("Entry"));
        var session=new SessionMachine();var engine=new PlaybackEngine(input,session,host){BaseDirectory=root};
        await engine.PlayAsync([
            new(){Kind=ActionKind.WaitWindow,Target=new("MacroStudio.TestLab","MacroStudio Visual Lab",window.Left,window.Top,window.Width,window.Height)},
            new(){Kind=ActionKind.WaitPixel,X=ocr.X+ocr.Width-5,Y=ocr.Y+2,Detection=new(){Color="#FFFFFF",TimeoutMs=500}},
            new(){Kind=ActionKind.Screenshot,Detection=new(){Region=ocr},Data=new(){Variable="capture",File="ocr-capture.png"}},
            new(){Kind=ActionKind.OcrText,Detection=new(){Region=ocr},Data=new(){Variable="ocr"}},
            new(){Kind=ActionKind.OcrFind,Detection=new(){Region=ocr},Data=new(){Variable="position",Value="AUTOMATION READY 42"}},
            new(){Kind=ActionKind.Branch,Data=new(){Value="${ocr}",Operation="contains",Operand="READY"},Flow=new(){Destination="type",Otherwise="end"}},
            new(){Kind=ActionKind.Label,Flow=new(){Label="type"}},new(){Kind=ActionKind.MouseButton,X=entry.X+entry.Width/2,Y=entry.Y+entry.Height/2,IsDown=true},new(){Kind=ActionKind.MouseButton,X=entry.X+entry.Width/2,Y=entry.Y+entry.Height/2},new(){Kind=ActionKind.Text,Text="${ocr}"},new(){Kind=ActionKind.Label,Flow=new(){Label="end"}}
        ],new(),timeout.Token);await Task.Delay(180);Check(Read().GetProperty("Text").GetString()==engine.Context!.Variables.Get("ocr").Value,"OCR variable did not reach the actual text box");Check(engine.Context.Variables.Get("position").Type==VariableType.Coordinates&&File.Exists(Path.Combine(root,"ocr-capture.png")));
        bool packagedCli=false;var packageDirectory=Environment.GetEnvironmentVariable("MACROSTUDIO_PACKAGE_DIRECTORY");
        if(!string.IsNullOrWhiteSpace(packageDirectory)){
            await hooks.ConfigureAsync([new("Stop",0,116)],false); // Leave Escape available to the separate CLI process.
            var macro=Path.Combine(root,"packaged-cli.json");var output=Path.Combine(root,"packaged-cli-ocr.txt");if(File.Exists(output))File.Delete(output);
            using(var captured=Cv2.ImRead(Path.Combine(root,"ocr-capture.png")))using(var crop=new Mat(captured,new Rect(0,0,Math.Min(900,captured.Width),captured.Height)))crop.SaveImage(Path.Combine(root,"cli-template.png"));
            await MacroStore.SaveAsync(macro,new(){Actions=[new(){Kind=ActionKind.WaitImage,Detection=new(){Image="cli-template.png",Region=ocr,TemplateDpi=initial.GetProperty("Dpi").GetDouble(),TimeoutMs=3000}},new(){Kind=ActionKind.Screenshot,Detection=new(){Region=ocr},Data=new(){Variable="capture",File="packaged-cli-capture.png"}},new(){Kind=ActionKind.OcrText,Detection=new(){Region=ocr},Data=new(){Variable="ocr"}},new(){Kind=ActionKind.WriteText,Data=new(){File="packaged-cli-ocr.txt",Value="${ocr}"}}]});
            using var cli=Process.Start(new ProcessStartInfo(Path.Combine(Path.GetFullPath(packageDirectory),"MacroStudio.exe")){ArgumentList={"--run",macro,"--timeout","10","--log",Path.Combine(root,"packaged-cli.log")},UseShellExecute=false})!;
            try{using var done=new CancellationTokenSource(15000);await cli.WaitForExitAsync(done.Token);Check(cli.ExitCode==0,"Packaged CLI exit "+cli.ExitCode);Check(await File.ReadAllTextAsync(output)==engine.Context!.Variables.Get("ocr").Value,"Packaged CLI OCR output differs");packagedCli=true;}finally{if(!cli.HasExited)cli.Kill();}
        }
        File.WriteAllText(Path.Combine(root,"visual-result.json"),JsonSerializer.Serialize(new{MovedClick=true,DelayedClick=true,Disappearance=true,RegionChange=true,PixelColor=true,WindowWait=true,AbsentTimeout=true,AbsentMs=absentMs,OcrToActualTextEntry=true,OcrFind=true,Branch=true,Screenshot=true,PackagedCli=packagedCli}));
    }finally{try{cleanup?.ReleaseAll();}finally{lab.CloseMainWindow();await Task.Delay(100);}}
}));
int failed=0;foreach(var(name,run)in tests){try{await run();Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;Console.WriteLine("FAIL "+name+": "+ex);}}Console.WriteLine($"{tests.Count-failed}/{tests.Count} advanced checks passed");return failed==0?0:1;

